package org.sleepwell.app;

import android.Manifest;
import android.content.*;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.database.sqlite.*;
import android.net.Uri;
import android.provider.CalendarContract;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Reviewed local CalendarContract insertion. Never updates/deletes calendar or recording rows. */
final class CalendarEventWrites {
 static final String DATABASE="calendar_event_receipts_v1.db";
 static final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(r,"Calendar event exports"));
 interface Provider {boolean allowed();List<Calendar> calendars();List<Event> find(String marker);Uri insert(Request request);}
 interface Factory {Provider open(Context c);}
 static final Factory PLATFORM=Platform::new;static Factory factory=PLATFORM;
 static final class Calendar {final long id;final String name,fingerprint;Calendar(long id,String name,String fingerprint){this.id=id;this.name=name;this.fingerprint=fingerprint;}}
 static final class Event {final long id,calendar,start,end;final String title,note,zone;Event(long id,long calendar,long start,long end,String title,String note,String zone){this.id=id;this.calendar=calendar;this.start=start;this.end=end;this.title=title;this.note=note;this.zone=zone;}boolean matches(Request r){return calendar==r.calendar&&start==r.start&&end==r.end&&title.equals(r.title)&&hash(note).equals(r.noteHash)&&zone.equals(r.zone);}}
 static final class Source {final CalendarEventDraft draft;final String fingerprint,identity;Source(CalendarEventDraft draft,String fingerprint,String identity){this.draft=draft;this.fingerprint=fingerprint;this.identity=identity;}}
 static final class Receipt {final String token,state,issue,calendar,title;final long event,updated;Receipt(Cursor c){token=c.getString(0);state=c.getString(1);issue=c.getString(2);calendar=c.getString(3);title=receiptTitle(c.getString(4));event=c.getLong(5);updated=c.getLong(6);}String label(){return state.equals("VERIFIED")?"Saved locally":state.equals("PREPARED")?"Not inserted":state.equals("INSERTING")||state.equals("UNCERTAIN")?"Outcome needs checking":state;}}
 static final class Request {
  final String token,key,source,calendarFingerprint,calendarName,title,note,noteHash,zone;final long record,calendar,start,end;
  Request(long record,Source source,Calendar calendar,String title,boolean notes){if(record<=0||calendar.id<=0)throw new IllegalArgumentException("Choose an existing record and writable calendar.");this.token=UUID.randomUUID().toString();this.record=record;this.source=source.fingerprint;this.calendar=calendar.id;calendarFingerprint=calendar.fingerprint;calendarName=calendar.name;this.title=title.trim();if(this.title.isEmpty()||this.title.length()>200)throw new IllegalArgumentException("Enter an event title of 1–200 characters.");start=source.draft.start;end=source.draft.end;zone=source.draft.zone;note=notes?source.draft.note:"";noteHash=hash(note);key=hash(new JSONArray().put(record).put(source.identity).put(this.calendar).put(start).put(end).put(zone).toString());}
  Request(Cursor c){try{token=c.getString(0);key=c.getString(1);record=c.getLong(2);source=c.getString(3);calendar=c.getLong(4);calendarFingerprint=c.getString(5);calendarName=c.getString(6);JSONArray p=new JSONArray(c.getString(7));title=p.getString(0);note="";noteHash=p.getString(1);start=p.getLong(2);end=p.getLong(3);zone=p.getString(4);}catch(JSONException invalid){throw new IllegalStateException("The saved export request is unreadable.",invalid);}}
  Request(Request fresh,String token){this.token=token;key=fresh.key;record=fresh.record;source=fresh.source;calendar=fresh.calendar;calendarFingerprint=fresh.calendarFingerprint;calendarName=fresh.calendarName;title=fresh.title;note=fresh.note;noteHash=fresh.noteHash;zone=fresh.zone;start=fresh.start;end=fresh.end;}
  String marker(){return "sleepwell-calendar://request/"+token;}
  String payload(){return new JSONArray().put(title).put(noteHash).put(start).put(end).put(zone).toString();}
 }
 static final class State {
  final boolean busy,attempting;final Source source;final List<Calendar> calendars;final List<Receipt> receipts;final String error,status;
  State(boolean busy,boolean attempting,Source source,List<Calendar> calendars,List<Receipt> receipts,String error,String status){this.busy=busy;this.attempting=attempting;this.source=source;this.calendars=List.copyOf(calendars);this.receipts=List.copyOf(receipts);this.error=error;this.status=status;}
 }
 private static final Map<Long,Job> jobs=new LinkedHashMap<>();
 static synchronized Job get(Context c,long id){Job j=jobs.get(id);if(j==null||j.records!=Records.factory||j.providers!=factory){if(jobs.size()>=16)jobs.entrySet().removeIf(e->!e.getValue().state.busy);j=new Job(c,id);jobs.put(id,j);}return j;}
 static boolean allowed(Context c){return c.checkSelfPermission(Manifest.permission.READ_CALENDAR)==PackageManager.PERMISSION_GRANTED&&c.checkSelfPermission(Manifest.permission.WRITE_CALENDAR)==PackageManager.PERMISSION_GRANTED;}
 static final class Job {
  final Context context;final long id;final Records.Factory records;final Factory providers;final Provider provider;final AtomicBoolean cancelled=new AtomicBoolean();
  volatile State state=new State(false,false,null,List.of(),List.of(),"","");
  Job(Context c,long id){context=c.getApplicationContext();this.id=id;records=Records.factory;providers=factory;provider=providers.open(context);}
  private void owners(){if(records!=Records.factory||providers!=factory)throw new IllegalStateException("The record source changed. Reopen this screen.");}
  private void platformAllowed(){owners();if(records!=Records.PRODUCTION&&providers==PLATFORM)throw new IllegalStateException("Direct calendar access is unavailable for this record source.");if(!provider.allowed())throw new SecurityException("Calendar access is unavailable. Allow access and review again.");}
  synchronized boolean begin(){if(state.busy)return false;cancelled.set(false);State s=state;state=new State(true,false,s.source,s.calendars,s.receipts,"","Working…");return true;}
  void cancel(){cancelled.set(true);}
  void load(){if(!begin())return;worker.execute(()->{Source found=null;List<Calendar> calendars=List.of();List<Receipt> receipts=List.of();String error="";try{owners();try(Journal journal=new Journal(context)){receipts=journal.receipts(id);}try{found=read();}catch(RuntimeException missing){error=message(missing);}if(provider.allowed()&&(records==Records.PRODUCTION||providers!=PLATFORM))calendars=provider.calendars();}catch(RuntimeException failed){error=message(failed);}state=new State(false,false,found,calendars,receipts,error,"");});}
  private Source read(){owners();try(Store store=records.open(context)){SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{RecordEntry r=Records.get(store,id);CalendarEventDraft draft=CalendarEventExport.draft(r);JSONArray periods=new JSONArray();for(RecordIntervals.Span span:r.coverage())periods.put(new JSONArray().put(span.start).put(span.end));JSONArray identity=new JSONArray().put(id).put(r.rawStart).put(r.rawEnd).put(r.active==null?JSONObject.NULL:r.active).put(r.source).put(r.origin).put(r.zone).put(r.sensor).put(r.sensorConfig).put(r.soundAnalysis).put(r.healthConnect).put(r.interrupted).put(r.clockChanged).put(r.updated).put(r.edited).put(r.edit.start).put(r.edit.end).put(r.edit.note).put(TagCodec.encode(r.edit)).put(periods).put(r.awake.portable());db.setTransactionSuccessful();return new Source(draft,hash(identity.toString()),hash(new JSONArray().put(id).put(r.rawStart).put(r.rawEnd).put(r.source).put(r.origin).toString()));}finally{db.endTransaction();}}}
  private void sourceUnchanged(Request request){owners();if(!read().fingerprint.equals(request.source))throw new IllegalStateException("This record changed or was removed. Reload and review before saving.");}
  private void destinationUnchanged(Request request){platformAllowed();for(Calendar c:provider.calendars())if(c.id==request.calendar&&c.fingerprint.equals(request.calendarFingerprint))return;throw new IllegalStateException("The selected calendar changed or is no longer writable. Reload and choose again.");}
  void save(Source reviewed,Calendar destination,String title,boolean notes){if(reviewed==null||destination==null||!begin())return;worker.execute(()->{String error="",status="";Request request=null;boolean attempted=false,transitioned=false;try(Journal journal=new Journal(context)){
   request=new Request(id,reviewed,destination,title,notes);platformAllowed();sourceUnchanged(request);destinationUnchanged(request);if(cancelled.get())throw new IllegalStateException("Cancelled before insertion.");
   Request unresolved=journal.unresolved(id);if(unresolved!=null&&!unresolved.key.equals(request.key)){status=reconcile(journal,unresolved)+" Review this earlier request before any new export.";finish(journal,error,status);return;}
   Request previous=journal.byKey(request.key);if(previous!=null){String saved=journal.state(previous.token);if(!saved.equals("PREPARED")){request=previous;status=reconcile(journal,request)+" This period already has an export request; changing its title or note does not create or update an event.";finish(journal,error,status);return;}request=new Request(request,previous.token);journal.review(request);}
   else journal.prepare(request);
   // Establish that this provider supports observable ownership before any creation.
   List<Event> prior=provider.find(request.marker());if(!prior.isEmpty()){status=verify(journal,request,prior);finish(journal,error,status);return;}
   sourceUnchanged(request);destinationUnchanged(request);if(cancelled.get())throw new IllegalStateException("Cancelled before insertion.");
   journal.update(request.token,"INSERTING",0,"The provider outcome has not been verified.");transitioned=true;state=new State(true,true,state.source,state.calendars,state.receipts,"","Saving the reviewed event…");
   // No record DB transaction is held across provider I/O. A later source edit does not rewrite the reviewed event.
   if(cancelled.get()){journal.update(request.token,"PREPARED",0,"Cancelled before insertion.");throw new IllegalStateException("Cancelled before insertion.");}sourceUnchanged(request);platformAllowed();
   attempted=true;Uri created=provider.insert(request);if(created==null)throw new IllegalStateException("The calendar provider did not return a receipt.");
   status=verify(journal,request,provider.find(request.marker()));
  }catch(RuntimeException failed){error=message(failed);if(request!=null)try(Journal journal=new Journal(context)){String phase=journal.state(request.token);if(attempted&&!phase.equals("VERIFIED")){journal.update(request.token,"UNCERTAIN",0,"The event may have been created. Check this request; do not repeat it.");error="The event may have been saved. Use Check receipt; no second event will be inserted.";}else if(attempted){error="The event was saved and verified locally; receipt cleanup needs attention.";}else if(phase.equals("PREPARED")||transitioned&&phase.equals("INSERTING"))journal.update(request.token,"PREPARED",0,error);}catch(RuntimeException journalFailed){error=attempted?"The event may have been saved, but its receipt could not be stored. Do not repeat the export.":error;}}
   try(Journal journal=new Journal(context)){finish(journal,error,status);}catch(RuntimeException failed){State s=state;state=new State(false,false,s.source,s.calendars,s.receipts,error.isEmpty()?"Export status is unavailable. Do not repeat a possibly completed write.":error,status);}
  });}
  void check(String token){if(!begin())return;worker.execute(()->{String error="",status="";try(Journal journal=new Journal(context)){platformAllowed();Request request=journal.byToken(token,id);if(request==null)throw new IllegalStateException("This request is no longer available.");status=reconcile(journal,request);finish(journal,"",status);return;}catch(RuntimeException failed){error=message(failed);}try(Journal journal=new Journal(context)){finish(journal,error,status);}catch(RuntimeException failed){State s=state;state=new State(false,false,s.source,s.calendars,s.receipts,error,status);}});}
  private String reconcile(Journal journal,Request request){platformAllowed();return verify(journal,request,provider.find(request.marker()));}
  private String verify(Journal journal,Request request,List<Event> events){if(events.size()==1&&events.get(0).matches(request)){journal.update(request.token,"VERIFIED",events.get(0).id,"");return "Saved to the local calendar provider. Remote calendar sync is handled by your calendar app.";}String issue=events.isEmpty()?"No matching event could be verified. It may be deleted, delayed or unobservable; no duplicate will be inserted.":"The marked event was changed or appears more than once. Existing events were left unchanged.";journal.update(request.token,"UNCERTAIN",events.size()==1?events.get(0).id:0,issue);return issue;}
  private void finish(Journal journal,String error,String status){State s=state;state=new State(false,false,s.source,s.calendars,journal.receipts(id),error,status);}
  boolean await(long millis)throws InterruptedException{try{worker.submit(()->{}).get(millis,TimeUnit.MILLISECONDS);return true;}catch(ExecutionException|TimeoutException e){return false;}}
 }
 private static final class Journal extends SQLiteOpenHelper {
  Journal(Context c){super(c,DATABASE,null,1);}
  @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE requests(token TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,record_id INTEGER NOT NULL,source TEXT NOT NULL,calendar_id INTEGER NOT NULL,calendar_fingerprint TEXT NOT NULL,calendar_name TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL,event_id INTEGER NOT NULL DEFAULT 0,issue TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL,updated INTEGER NOT NULL)");}
  @Override public void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion){throw new IllegalStateException("Calendar receipt version is unavailable.");}
  private final String[] requestColumns={"token","request_key","record_id","source","calendar_id","calendar_fingerprint","calendar_name","payload"};
  Request byKey(String key){try(Cursor c=getReadableDatabase().query("requests",requestColumns,"request_key=?",new String[]{key},null,null,null)){return c.moveToFirst()?new Request(c):null;}}
  Request byToken(String token,long record){try(Cursor c=getReadableDatabase().query("requests",requestColumns,"token=? AND record_id=?",new String[]{token,""+record},null,null,null)){return c.moveToFirst()?new Request(c):null;}}
  Request unresolved(long record){try(Cursor c=getReadableDatabase().query("requests",requestColumns,"record_id=? AND state IN ('INSERTING','UNCERTAIN')",new String[]{""+record},null,null,"created ASC","1")){return c.moveToFirst()?new Request(c):null;}}
  String state(String token){try(Cursor c=getReadableDatabase().query("requests",new String[]{"state"},"token=?",new String[]{token},null,null,null)){return c.moveToFirst()?c.getString(0):"";}}
  void prepare(Request r){SQLiteDatabase db=getWritableDatabase();try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM requests",null)){if(!c.moveToFirst()||c.getLong(0)>=2048)throw new IllegalStateException("Calendar export history is full; use the calendar-app compose option.");}ContentValues v=new ContentValues();v.put("token",r.token);v.put("request_key",r.key);v.put("record_id",r.record);v.put("source",r.source);v.put("calendar_id",r.calendar);v.put("calendar_fingerprint",r.calendarFingerprint);v.put("calendar_name",r.calendarName);v.put("payload",r.payload());v.put("state","PREPARED");v.put("created",System.currentTimeMillis());v.put("updated",System.currentTimeMillis());db.insertOrThrow("requests",null,v);}
  void review(Request r){ContentValues v=new ContentValues();v.put("source",r.source);v.put("calendar_fingerprint",r.calendarFingerprint);v.put("calendar_name",r.calendarName);v.put("payload",r.payload());v.put("updated",System.currentTimeMillis());if(getWritableDatabase().update("requests",v,"token=? AND state='PREPARED'",new String[]{r.token})!=1)throw new IllegalStateException("The prepared request changed. Check its receipt before continuing.");}
  void update(String token,String state,long event,String issue){ContentValues v=new ContentValues();v.put("state",state);v.put("event_id",event);v.put("issue",issue);v.put("updated",System.currentTimeMillis());if(getWritableDatabase().update("requests",v,"token=?",new String[]{token})!=1)throw new IllegalStateException("The calendar request receipt could not be saved.");}
  List<Receipt> receipts(long id){List<Receipt> out=new ArrayList<>();try(Cursor c=getReadableDatabase().query("requests",new String[]{"token","state","issue","calendar_name","payload","event_id","updated"},"record_id=?",new String[]{""+id},null,null,"updated DESC","20")){while(c.moveToNext()){Receipt r=new Receipt(c);out.add(r);}}return out;}
 }
 private static final class Platform implements Provider {
  final Context context;final ContentResolver resolver;Platform(Context c){context=c.getApplicationContext();resolver=context.getContentResolver();}
  public boolean allowed(){return CalendarEventWrites.allowed(context);}
  private void require(){if(!allowed())throw new SecurityException("Allow calendar read and write access, then review again.");}
  public List<Calendar> calendars(){require();List<Calendar> out=new ArrayList<>();String[] cols={CalendarContract.Calendars._ID,CalendarContract.Calendars.CALENDAR_DISPLAY_NAME,CalendarContract.Calendars.ACCOUNT_NAME,CalendarContract.Calendars.ACCOUNT_TYPE,CalendarContract.Calendars.NAME,CalendarContract.Calendars.CALENDAR_ACCESS_LEVEL};try(Cursor c=resolver.query(CalendarContract.Calendars.CONTENT_URI,cols,CalendarContract.Calendars.CALENDAR_ACCESS_LEVEL+">=?",new String[]{""+CalendarContract.Calendars.CAL_ACCESS_CONTRIBUTOR},CalendarContract.Calendars.CALENDAR_DISPLAY_NAME+" ASC")){if(c==null)throw new IllegalStateException("The calendar provider is unavailable.");while(c.moveToNext()){if(out.size()>=128)throw new IllegalStateException("Too many writable calendars. Use the calendar-app compose option.");JSONArray key=new JSONArray();for(int n=0;n<cols.length;n++)key.put(c.isNull(n)?JSONObject.NULL:c.getString(n));out.add(new Calendar(c.getLong(0),c.isNull(1)?"Calendar "+c.getLong(0):c.getString(1),hash(key.toString())));}}return List.copyOf(out);}
  public List<Event> find(String marker){require();List<Event> out=new ArrayList<>();String[] cols={CalendarContract.Events._ID,CalendarContract.Events.CALENDAR_ID,CalendarContract.Events.DTSTART,CalendarContract.Events.DTEND,CalendarContract.Events.TITLE,CalendarContract.Events.DESCRIPTION,CalendarContract.Events.EVENT_TIMEZONE};String where=CalendarContract.Events.CUSTOM_APP_PACKAGE+"=? AND "+CalendarContract.Events.CUSTOM_APP_URI+"=? AND "+CalendarContract.Events.DELETED+"=0";try(Cursor c=resolver.query(CalendarContract.Events.CONTENT_URI,cols,where,new String[]{context.getPackageName(),marker},null)){if(c==null)throw new IllegalStateException("This calendar provider cannot verify app-owned export requests.");while(c.moveToNext()){if(out.size()>=2)break;out.add(new Event(c.getLong(0),c.getLong(1),c.getLong(2),c.getLong(3),text(c,4),text(c,5),text(c,6)));}}return out;}
  public Uri insert(Request r){require();ContentValues v=new ContentValues();v.put(CalendarContract.Events.CALENDAR_ID,r.calendar);v.put(CalendarContract.Events.DTSTART,r.start);v.put(CalendarContract.Events.DTEND,r.end);v.put(CalendarContract.Events.EVENT_TIMEZONE,r.zone);v.put(CalendarContract.Events.TITLE,r.title);v.put(CalendarContract.Events.DESCRIPTION,r.note);v.put(CalendarContract.Events.ALL_DAY,0);v.put(CalendarContract.Events.HAS_ALARM,0);v.put(CalendarContract.Events.ACCESS_LEVEL,CalendarContract.Events.ACCESS_PRIVATE);v.put(CalendarContract.Events.AVAILABILITY,CalendarContract.Events.AVAILABILITY_FREE);v.put(CalendarContract.Events.CUSTOM_APP_PACKAGE,context.getPackageName());v.put(CalendarContract.Events.CUSTOM_APP_URI,r.marker());return resolver.insert(CalendarContract.Events.CONTENT_URI,v);}
  private String text(Cursor c,int n){return c.isNull(n)?"":c.getString(n);}
 }
 private static String receiptTitle(String encoded){try{return new JSONArray(encoded).getString(0);}catch(JSONException invalid){return "Saved export request";}}
 private static String hash(String value){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
 private static String message(RuntimeException e){return e instanceof SecurityException?"Calendar permission is unavailable or was revoked. No unverified request will be replayed.":e.getMessage()==null?"Calendar export is unavailable. Try reloading the review.":e.getMessage();}
 private CalendarEventWrites(){}
}